SELECT '927ecdf1-afaf-581a-aa48-c341e4413222',qt.id,dl.id,tp.id,ch.id,s.id,'CH1-Q01: Which of the following is a correctly balanced equation for the reaction of magnesium with dilute hydrochloric acid? $\text{Mg} + \text{HCl} \rightarrow \text{MgCl}_2 + \text{H}_2$','LHS: 1 Mg, 2 H, 2 Cl. RHS: $\text{MgCl}_2$ gives 1 Mg and 2 Cl, $\text{H}_2$ gives 2 H. Hence option B balances all atoms.',1,0.25,45,'{"balancing","acids","cbse-pyq"}'::text[],'{"seed_code":"Q01","topic_code":"balancing-equations","subtopic_code":"hit-and-trial"}'::jsonb,true,true,'mcq','Which of the following is a correctly balanced equation for the reaction of magnesium with dilute hydrochloric acid? $\text{Mg} + \text{HCl} \rightarrow \text{MgCl}_2 + \text{H}_2$',NULL,st.id,1,'recall',0.25,45,'CBSE',2023,'en','published','manual'
FROM question_types qt, difficulty_levels dl, topics tp JOIN chapters ch ON tp.chapter_id=ch.id JOIN subjects s ON ch.subject_id=s.id JOIN classes c ON s.class_id=c.id JOIN boards b ON c.board_id=b.id LEFT JOIN subtopics st ON st.topic_id=tp.id AND st.code='hit-and-trial'
WHERE qt.code='single_correct' AND dl.code='easy' AND b.code='cbse' AND c.code='class-10' AND s.code='science' AND ch.code='chemical-reactions' AND tp.code='balancing-equations'
