SELECT '7e48654e-7ae2-5835-abb4-5f656b64c551',qt.id,dl.id,tp.id,ch.id,s.id,'CH1-Q02: Quicklime ($\text{CaO}$) reacts with water to form slaked lime with evolution of heat: $\text{CaO} + \text{H}_2\text{O} \rightarrow \text{Ca(OH)}_2 + \text{Heat}$. This reaction is:','Two substances combine into a single product (combination) and heat is evolved (exothermic).',1,0.25,40,'{"combination","quicklime","exothermic"}'::text[],'{"seed_code":"Q02","topic_code":"types-of-reactions","subtopic_code":"combination-reactions"}'::jsonb,true,true,'mcq','Quicklime ($\text{CaO}$) reacts with water to form slaked lime with evolution of heat: $\text{CaO} + \text{H}_2\text{O} \rightarrow \text{Ca(OH)}_2 + \text{Heat}$. This reaction is:',NULL,st.id,1,'recall',0.25,40,'CBSE',2020,'en','published','manual'
FROM question_types qt, difficulty_levels dl, topics tp JOIN chapters ch ON tp.chapter_id=ch.id JOIN subjects s ON ch.subject_id=s.id JOIN classes c ON s.class_id=c.id JOIN boards b ON c.board_id=b.id LEFT JOIN subtopics st ON st.topic_id=tp.id AND st.code='combination-reactions'
