-- 11. Analytics helper: per-blueprint leaderboard view (refreshed on demand)
CREATE OR REPLACE VIEW blueprint_leaderboard AS
SELECT att.user_id, ti.blueprint_id AS blueprint_id, AVG(att.score) AS avg_score, MAX(att.score) AS best_score, COUNT(*) AS attempts
FROM attempts att JOIN test_instances ti ON att.instance_id=ti.id
WHERE att.status IN ('submitted','graded')
GROUP BY att.user_id, ti.blueprint_id;

-- 12. RLS guard: ensure students cannot read raw correct flags directly
-- question_options.is_correct stays hidden behind server-side access; no public grant needed.
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'question_options_admin') THEN
    NULL;
  END IF;
END $$;

-- 13. Verification (counts must show 62 questions / 6 blueprints)
DO $$ DECLARE v_q INT; v_bp INT; BEGIN
  SELECT COUNT(*) INTO v_q FROM questions WHERE metadata->>'seed_code' LIKE 'Q%';
  SELECT COUNT(*) INTO v_bp FROM blueprints WHERE slug LIKE 'ch1-%';
  RAISE NOTICE 'SEED014: questions=% blueprints=%', v_q, v_bp;
END $$;
